"""Task ABI: a KORE task = a driver contract + shapes + a production baseline.

Each task lives in ``kore/tasks/<task_id>/`` with:
    task.yaml      - metadata (schema below)
    reference.py   - torch-fp32 oracle for correctness
    seed_triton.py - a compiling (not necessarily fast) seed kernel
    driver.py      - the KernelForge verifier contract:
        correctness mode : writes candidate to kernel.py, prints
                           ``SNR: <db>`` / ``allclose: <bool>`` / ``max_diff: <x>``
        --bench-mode --impl {reference|candidate} : prints ``median_ms: <x>``
                           where ``reference`` == the REAL production op (AITER/hipBLASLt).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Optional

import yaml


@dataclass(frozen=True)
class Shape:
    name: str
    dims: dict[str, int]

    def as_args(self) -> list[str]:
        # drivers parse a single ``--shape "K1=V1,K2=V2"`` string.
        if not self.dims:
            return []
        spec = ",".join(f"{k}={v}" for k, v in self.dims.items())
        return ["--shape", spec]


@dataclass
class Task:
    task_id: str
    operation: str
    dtype: str
    backend: str
    gpu_target: str
    dir: Path
    seed_kernel_name: str
    snr_threshold: float
    comparison_baseline: str
    shapes: list[Shape] = field(default_factory=list)
    raw: dict[str, Any] = field(default_factory=dict)

    @property
    def driver_path(self) -> Path:
        return self.dir / "driver.py"

    @property
    def reference_path(self) -> Path:
        return self.dir / "reference.py"

    @property
    def seed_path(self) -> Path:
        return self.dir / self.seed_kernel_name

    @property
    def seed_source(self) -> str:
        return self.seed_path.read_text()

    def shape(self, name: str) -> Optional[Shape]:
        for s in self.shapes:
            if s.name == name:
                return s
        return None

    @classmethod
    def from_dir(cls, d: Path) -> "Task":
        meta = yaml.safe_load((d / "task.yaml").read_text())
        shapes: list[Shape] = []
        raw_shapes = meta.get("shapes", {}) or {}
        for key, val in raw_shapes.items():
            if key == "validation" and isinstance(val, list):
                for i, dims in enumerate(val):
                    shapes.append(Shape(f"validation_{i}", dict(dims)))
            elif isinstance(val, dict):
                shapes.append(Shape(key, dict(val)))
        targets = meta.get("targets", {}) or {}
        return cls(
            task_id=meta["task_id"],
            operation=meta.get("operation", meta["task_id"]),
            dtype=meta.get("dtype", "fp32"),
            backend=meta.get("backend", "triton"),
            gpu_target=meta.get("gpu_target", "gfx942"),
            dir=d,
            seed_kernel_name=meta.get("seed_kernel_name", "seed_triton.py"),
            snr_threshold=float(meta.get("snr_threshold", targets.get("snr_db", 30.0))),
            comparison_baseline=targets.get("comparison_baseline", "torch"),
            shapes=shapes,
            raw=meta,
        )

"""Discover and load KORE tasks from ``kore/tasks/<id>/task.yaml``.

Also defines the **train / held-out generalization split**. A whole operator
*family* (plus any arch-specific task) is deterministically RESERVED as held-out
so that training data-generation never sees it and eval measures generalization
to an unseen family — mirroring KernelBench/GEAK's train-vs-heldout discipline.
"""

from __future__ import annotations

import random
from functools import lru_cache
from pathlib import Path

from kore.tasks.base import Task

TASKS_DIR = Path(__file__).resolve().parent

# The arch we train on; anything else is arch-specific and is held out (e.g. a
# gfx950/CDNA4-only kernel must never leak into the gfx942 training set).
TRAIN_ARCH = "gfx942"

# Whole operator families reserved for the held-out generalization set. Reserving
# an ENTIRE family (not a random subset) is what makes this a true generalization
# test: the policy is trained without ever seeing the attention family.
HELDOUT_FAMILIES: tuple[str, ...] = ("attention",)


def operator_family(task: Task) -> str:
    """Coarse operator family for a task (used for the generalization split)."""
    op = (getattr(task, "operation", None) or getattr(task, "task_id", "") or "").lower()
    if "attn" in op or "attention" in op:
        return "attention"
    if "topk" in op:
        return "moe_router"
    if "moe" in op:
        return "moe"
    if "rmsnorm" in op:
        return "rmsnorm"
    if "layernorm" in op:
        return "layernorm"
    if "gemm" in op or "matmul" in op:
        return "gemm"
    if "quant" in op:
        return "quant"
    if "rope" in op:
        return "rope"
    if "softmax" in op:
        return "softmax"
    if "gelu" in op or "silu" in op or "relu" in op:
        return "activation"
    return op or "other"


def is_heldout(task: Task) -> bool:
    """A task is held out if its family is reserved OR it is arch-specific."""
    if operator_family(task) in HELDOUT_FAMILIES:
        return True
    if (getattr(task, "gpu_target", None) or TRAIN_ARCH) != TRAIN_ARCH:
        return True
    return False


@lru_cache(maxsize=1)
def _discover() -> dict[str, Task]:
    tasks: dict[str, Task] = {}
    for yml in sorted(TASKS_DIR.glob("*/task.yaml")):
        try:
            t = Task.from_dir(yml.parent)
            tasks[t.task_id] = t
        except Exception as e:  # noqa: BLE001
            print(f"[registry] skip {yml.parent.name}: {e}")
    return tasks


def all_tasks() -> list[Task]:
    return list(_discover().values())


def task_ids() -> list[str]:
    return list(_discover().keys())


def get_task(task_id: str) -> Task:
    tasks = _discover()
    if task_id not in tasks:
        raise KeyError(f"unknown task '{task_id}'; known: {sorted(tasks)}")
    return tasks[task_id]


# --------------------------------------------------------------------------- #
# Train / held-out generalization split
# --------------------------------------------------------------------------- #
def heldout_tasks() -> list[Task]:
    """Tasks RESERVED for held-out generalization eval (never seen in training).

    Deterministic and independent of any seed — the reserved set is a function of
    the operator family + arch alone, so training data-gen can safely exclude it.
    """
    return [t for t in all_tasks() if is_heldout(t)]


def train_tasks() -> list[Task]:
    """Tasks available for training data-generation (complement of held-out)."""
    return [t for t in all_tasks() if not is_heldout(t)]


def heldout_families() -> set[str]:
    """The operator families that actually appear in the held-out split."""
    return {operator_family(t) for t in heldout_tasks()}


def split_tasks(seed: int = 0) -> dict[str, object]:
    """Deterministic train/held-out split.

    The held-out set is FIXED (reserved operator families + arch-specific tasks)
    regardless of ``seed`` so training can never leak into it; ``seed`` only
    controls the reproducible ordering WITHIN each split (useful for sharding or
    cross-validation folds). Returns
    ``{"train": [...], "heldout": [...], "seed": seed}``.
    """
    train = sorted(train_tasks(), key=lambda t: t.task_id)
    held = sorted(heldout_tasks(), key=lambda t: t.task_id)
    rng = random.Random(seed)
    rng.shuffle(train)
    rng.shuffle(held)
    return {"train": train, "heldout": held, "seed": seed}

"""Reference + inputs for the AMD-correct bf16 RMSNorm task.

Correctness oracle: exact torch-fp32 RMSNorm (mathematically exact).
Perf baseline (in driver, --impl reference): AITER ``rms_norm`` (CK) — the
kernel the production serving stack actually calls, NOT unfused torch.
"""

from __future__ import annotations

import torch

EPS = 1e-6


def parse_shape(shape_str: str) -> dict:
    if not shape_str or shape_str == "default":
        return {"M": 4096, "N": 4096}
    out = {}
    for kv in shape_str.split(","):
        k, v = kv.split("=")
        out[k.strip()] = int(v)
    return out


def get_inputs(shape: dict, dtype=torch.bfloat16, device="cuda", seed: int = 0):
    g = torch.Generator(device=device).manual_seed(seed)
    M, N = shape["M"], shape["N"]
    x = torch.randn((M, N), generator=g, device=device, dtype=torch.float32).to(dtype)
    w = torch.randn((N,), generator=g, device=device, dtype=torch.float32).to(dtype)
    return x, w


def rmsnorm_ref(x: torch.Tensor, weight: torch.Tensor, eps: float = EPS) -> torch.Tensor:
    """Exact fp32 oracle."""
    xf = x.float()
    var = xf.pow(2).mean(dim=-1, keepdim=True)
    y = xf * torch.rsqrt(var + eps)
    return (y * weight.float()).to(x.dtype)

"""Reference + inputs for the gated-MLP activation SiLU(gate)*up.

The fused MLP activation used by Llama/Mistral-style gated FFNs: a single
input of width ``2*N`` is split into (gate, up); output is ``silu(gate) * up``
of width ``N``.

Correctness oracle: exact torch-fp32 silu*mul.
Perf baseline (driver --impl reference): AITER ``silu_and_mul``.
"""

from __future__ import annotations

import torch


def parse_shape(shape_str: str) -> dict:
    if not shape_str or shape_str == "default":
        return {"M": 4096, "N": 14336}
    out = {}
    for kv in shape_str.split(","):
        k, v = kv.split("=")
        out[k.strip()] = int(v)
    return out


def get_inputs(shape: dict, dtype=torch.bfloat16, device="cuda", seed: int = 0):
    """Returns a single (M, 2*N) tensor: columns [0:N)=gate, [N:2N)=up."""
    g = torch.Generator(device=device).manual_seed(seed)
    M, N = shape["M"], shape["N"]
    x = torch.randn((M, 2 * N), generator=g, device=device, dtype=torch.float32).to(dtype)
    return (x,)


def silu_mul_ref(x: torch.Tensor) -> torch.Tensor:
    """Exact fp32 oracle. Input (M, 2N) -> output (M, N)."""
    n = x.shape[-1] // 2
    xf = x.float()
    gate, up = xf[..., :n], xf[..., n:]
    return (torch.nn.functional.silu(gate) * up).to(x.dtype)

