#include <iostream>
#include <vector>

#include <hip/hip_ext.h>
#include <hip/hip_fp16.h>
#include <hip/hip_runtime.h>

#include <rocwmma/rocwmma.hpp>

#include "common.hpp"

using rocwmma::accumulator;
using rocwmma::col_major;
using rocwmma::float32_t;
using rocwmma::matrix_a;
using rocwmma::matrix_b;
using rocwmma::row_major;

// Host sgemv validation
__host__ void sgemv_cpu_h(uint32_t         m,
                          uint32_t         n,
                          uint32_t         k,
                          float32_t const* a,
                          float32_t const* b,
                          float32_t*       c,
                          float32_t        alpha,
                          float32_t        beta)
{
    uint32_t lda = m;

    for(int i = 0; i < m; ++i)
    {
        float32_t accum = 0.0f;
        for(int h = 0; h < k; ++h)
        {
            accum += static_cast<float32_t>(a[h * lda + i]) * static_cast<float32_t>(b[h]);
        }
        c[i] = alpha * accum + beta * c[i];
    }
}

// Supports ROCWMMA_M/N square sizes of
// : 16 x 16
// : 32 x 32 ( only MI )
const int ROCWMMA_M = 16;
const int ROCWMMA_N = 16;

// Supports ROCWMMA_K sizes as
// : multiples of 16.
const int ROCWMMA_K = 16;

// AMDGCN default wave size
const uint32_t WAVE_SIZE = getWarpSize();

// Thread block
// : T_BLOCK_X must be multiple of WAVE_SIZE.
// Note: Each wave will compute one ROCWMMA_M x ROCWMMA_N output block
// Note: Workgroup will compute
//  T_BLOCK_X / WAVE_SIZE x T_BLOCK_Y output blocks
const int T_BLOCK_X = 16 * WAVE_SIZE;
const int T_BLOCK_Y = 1;

// The following device kernel is a naive implementation
// of blocked SGEMV. Each wave will compute one ROCWMMA_M x ROCWMMA_N
// output block of the m x k x 1 SGEMV, generalized as:
// y = alpha * (A) * x + beta * y
//
// In this simplified example, we assume:
//  A - Matrix of size m * k (col-major)
//  x - Vector of size k * 1 (col-major)
//  y - accumulator of size m * 1 (col-major)
// : Multiplication is NOT in-place, output is written to D matrix
// : No LDS required
//
// Note: This is a simplified implementation to demonstrate API usage in
// context of wave-level SGEMV computation, and is not optimized.
__global__ void sgemv_rocwmma_d(uint32_t         m,
                                uint32_t         n,
                                uint32_t         k,
                                float32_t const* a,
                                float32_t const* b,
                                float32_t*       c,
                                float32_t*       d,
                                uint32_t         lda,
                                uint32_t         ldb,
                                uint32_t         ldc,
                                uint32_t         ldd,
                                float32_t        alpha,
                                float32_t        beta)
{
    // Create frags
    auto fragA
        = rocwmma::fragment<matrix_a, ROCWMMA_M, ROCWMMA_N, ROCWMMA_K, float32_t, col_major>();
    auto fragB
        = rocwmma::fragment<matrix_b, ROCWMMA_M, ROCWMMA_N, ROCWMMA_K, float32_t, col_major>();
    auto fragC   = rocwmma::fragment<accumulator, ROCWMMA_M, ROCWMMA_N, ROCWMMA_K, float32_t>();
    auto fragAcc = rocwmma::fragment<accumulator, ROCWMMA_M, ROCWMMA_N, ROCWMMA_K, float32_t>();

    rocwmma::fill_fragment(fragAcc, 0.0f);

    int majorWarp = (blockIdx.x * blockDim.x + threadIdx.x) / rocwmma::Constants::AMDGCN_WAVE_SIZE;

    // Target C block
    int cRow = majorWarp * ROCWMMA_M;

    if(cRow < m)
    {
        // fragAcc = A x B
        for(int i = 0; i < k; i += ROCWMMA_K)
        {
            // Load the inputs
            rocwmma::load_matrix_sync(fragA, a + (cRow + i * lda), lda);
            rocwmma::load_matrix_sync(fragB, b + i, ldb);

            // Matrix multiply - accumulate using MFMA units
            rocwmma::mma_sync(fragAcc, fragA, fragB, fragAcc);
        }

        rocwmma::load_matrix_sync(fragC, c + cRow, ldc, rocwmma::mem_col_major);

        for(int i = 0; i < fragC.num_elements; i++)
        {
            fragC.x[i] = alpha * fragAcc.x[i] + beta * fragC.x[i];
        }

        // Store the output
        rocwmma::store_matrix_sync(d + cRow, fragC, ldc, rocwmma::mem_col_major);
    }
}

__host__ void sgemv_test(uint32_t m, uint32_t n, uint32_t k, float alpha, float beta)
{
    // Bounds check
    if(m % ROCWMMA_M || n % ROCWMMA_N || k % ROCWMMA_K)
    {
        std::cout << "Unsupported size!\n";
        return;
    }

    int lda = m;
    int ldb = k;
    int ldc = m;
    int ldd = ldc;

    std::cout << "Initializing host data..." << std::endl;
    // Initialize input matrices
    std::vector<float32_t> matrixA(m * k); // matrix
    std::vector<float32_t> matrixB(k * 1); // vector
    std::vector<float32_t> matrixC(m * 1, 1.0); //accum

    fillRand(matrixA.data(), m, k);
    fillRand(matrixB.data(), k, 1);

    std::cout << "Initializing device data..." << std::endl;
    // Allocate and copy device memory
    float32_t* d_a;
    float32_t* d_b;
    float32_t* d_c;

    const size_t bytesA = matrixA.size() * sizeof(float32_t);
    const size_t bytesB = matrixB.size() * sizeof(float32_t);
    const size_t bytesC = matrixC.size() * sizeof(float32_t);

    CHECK_HIP_ERROR(hipMalloc(&d_a, bytesA));
    CHECK_HIP_ERROR(hipMalloc(&d_b, bytesB));
    CHECK_HIP_ERROR(hipMalloc(&d_c, bytesC));

    CHECK_HIP_ERROR(hipMemcpy(d_a, matrixA.data(), bytesA, hipMemcpyHostToDevice));
    CHECK_HIP_ERROR(hipMemcpy(d_b, matrixB.data(), bytesB, hipMemcpyHostToDevice));
    CHECK_HIP_ERROR(hipMemcpy(d_c, matrixC.data(), bytesC, hipMemcpyHostToDevice));

    auto blockDim = dim3(T_BLOCK_X, T_BLOCK_Y);
    auto gridDim  = dim3(rocwmma::ceilDiv(m, ROCWMMA_M * T_BLOCK_X / WAVE_SIZE),
                        rocwmma::ceilDiv(n, ROCWMMA_N * T_BLOCK_Y));

    std::cout << "Launching sgemv kernel..." << std::endl;
    hipEvent_t startEvent, stopEvent;
    CHECK_HIP_ERROR(hipEventCreate(&startEvent));
    CHECK_HIP_ERROR(hipEventCreate(&stopEvent));

    hipExtLaunchKernelGGL(sgemv_rocwmma_d,
                          gridDim,
                          blockDim,
                          0, // sharedMemBytes
                          0, // stream
                          startEvent, // Event start
                          stopEvent, // event stop
                          0, // flags
                          m,
                          n,
                          k,
                          d_a,
                          d_b,
                          d_c,
                          d_c,
                          lda,
                          ldb,
                          ldc,
                          ldd,
                          alpha,
                          beta);

    auto elapsedTimeMs = 0.0f;
    CHECK_HIP_ERROR(hipEventSynchronize(stopEvent));
    CHECK_HIP_ERROR(hipEventDestroy(startEvent));
    CHECK_HIP_ERROR(hipEventDestroy(stopEvent));

    // Echo performance
    std::cout << "BlkM, BlkN, BlkK, "
              << "MatM, MatN, MatK, " << std::endl;

    std::cout << ROCWMMA_M << ", " << ROCWMMA_N << ", " << ROCWMMA_K << ", " << m << ", " << n
              << ", " << k << std::endl;

#if !NDEBUG

    std::cout << "Validating result with reference..." << std::endl;
    // Bring kernel result back to host
    std::vector<float32_t> matrixC_device(m, std::numeric_limits<float32_t>::signaling_NaN());
    CHECK_HIP_ERROR(hipMemcpy(matrixC_device.data(), d_c, bytesC, hipMemcpyDeviceToHost));

    // Setup and run reference computation
    std::vector<float32_t> matrixC_host(matrixC);
    sgemv_cpu_h(m, n, k, matrixA.data(), matrixB.data(), matrixC_host.data(), alpha, beta);

    auto res = compareEqual<float32_t>(matrixC_host.data(), matrixC_device.data(), m);

    if(std::get<0>(res) == false)
    {
        std::cout << "FAILED!\n";
    }
    else
    {
        std::cout << "PASSED!\n";
    }

    std::cout << "Max relative error: " << std::get<1>(res) << std::endl;

#endif // !NDEBUG

    // Release device memory
    CHECK_HIP_ERROR(hipFree(d_a));
    CHECK_HIP_ERROR(hipFree(d_b));
    CHECK_HIP_ERROR(hipFree(d_c));

    std::cout << "Finished!" << std::endl;
}

int main()
{
    const uint32_t m = 256;
    const uint32_t k = 256;
    const uint32_t n = T_BLOCK_Y * ROCWMMA_N;

    if(!isF32Supported())
    {
        std::cout << "f32 sgemv not supported on this device" << std::endl;
    }
    else
    {
        sgemv_test(m, n, k, 2.1f, 2.1f);
    }
    return 0;
}

#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
#include <cstdio>
#include <cstdint>
#include <vector>
#include <random>
#include <cmath>
#include <algorithm>
#include <functional>

#define HIP_CHECK(x) do { hipError_t e=(x); if(e!=hipSuccess){ \
  fprintf(stderr,"HIP error %s:%d: %s\n",__FILE__,__LINE__,hipGetErrorString(e)); \
  std::exit(1);} } while(0)

using bf16 = __hip_bfloat16;

// ---- device helpers ----
__device__ __forceinline__ float silu_f(float x){
  return x / (1.0f + expf(-x));
}

__global__ void silu_mul_kernel(
    bf16* __restrict__ out,          // [B, H]
    const bf16* __restrict__ in,     // [B, 2H]
    int64_t B, int64_t H)
{
  const int64_t token_idx = blockIdx.x;
  for (int64_t idx = threadIdx.x; idx < H; idx += blockDim.x) {
    const float x = __bfloat162float(in[token_idx * 2 * H + idx]);
    const float y = __bfloat162float(in[token_idx * 2 * H + H + idx]);
    out[token_idx * H + idx] = __float2bfloat16(silu_f(x) * y);
  }
}

static void fill_random(std::vector<bf16>& buf,
                        float lo=-3.f,float hi=3.f,uint32_t seed=123){
  std::mt19937 rng(seed);
  std::uniform_real_distribution<float> dist(lo,hi);
  for (auto& v: buf) v = __float2bfloat16(dist(rng));
}

static void host_ref(std::vector<bf16>& out,
                     const std::vector<bf16>& in,
                     int64_t B, int64_t H){
  auto silu_h = [](double x){ return x/(1.0+std::exp(-x)); };
  for (int64_t b=0;b<B;++b){
    int64_t in_row=b*(2*H), out_row=b*H;
    for (int64_t i=0;i<H;++i){
      float x = __bfloat162float(in[in_row+i]);
      float y = __bfloat162float(in[in_row+H+i]);
      out[out_row+i] = __float2bfloat16((float)(silu_h(x)*y));
    }
  }
}

static void max_diff(const std::vector<bf16>& a,
                     const std::vector<bf16>& b,
                     double& max_abs, double& max_rel){
  max_abs=0; max_rel=0;
  for (size_t i=0;i<a.size();++i){
    double va = (double)__bfloat162float(a[i]);
    double vb = (double)__bfloat162float(b[i]);
    double ad = std::abs(va-vb);
    double rd = ad/(std::abs(vb)+1e-8);
    max_abs = std::max(max_abs, ad);
    max_rel = std::max(max_rel, rd);
  }
}

static float time_kernel_ms(std::function<void()> launch,
                            int warmup=5,int iters=100){
  hipEvent_t s,t; HIP_CHECK(hipEventCreate(&s)); HIP_CHECK(hipEventCreate(&t));
  for(int i=0;i<warmup;++i) launch();
  HIP_CHECK(hipDeviceSynchronize());
  HIP_CHECK(hipEventRecord(s)); for(int i=0;i<iters;++i) launch();
  HIP_CHECK(hipEventRecord(t)); HIP_CHECK(hipEventSynchronize(t));
  float ms=0.f; HIP_CHECK(hipEventElapsedTime(&ms,s,t));
  HIP_CHECK(hipEventDestroy(s)); HIP_CHECK(hipEventDestroy(t)); return ms/iters;
}

int main(int argc, char** argv){
  int64_t B=4096, H=6400;
  for (int i=1;i<argc;++i){
    if (std::string(argv[i])=="--B" && i+1<argc) B=std::atoll(argv[++i]);
    else if (std::string(argv[i])=="--H" && i+1<argc) H=std::atoll(argv[++i]);
    else {
      printf("Usage: %s [--B <batch>] [--H <hidden>]\n", argv[0]);
      return 0;
    }
  }

  size_t in_e  = (size_t)B*(size_t)(2*H);
  size_t out_e = (size_t)B*(size_t)H;

  std::vector<bf16> h_in(in_e), h_out(out_e), h_ref(out_e);
  fill_random(h_in);

  bf16 *d_in=nullptr, *d_out=nullptr;
  HIP_CHECK(hipMalloc(&d_in,  in_e*sizeof(bf16)));
  HIP_CHECK(hipMalloc(&d_out, out_e*sizeof(bf16)));
  HIP_CHECK(hipMemcpy(d_in, h_in.data(), in_e*sizeof(bf16), hipMemcpyHostToDevice));

  dim3 grid(B), block(1024);
  auto launch = [&](){
    hipLaunchKernelGGL(silu_mul_kernel, grid, block, 0, 0, d_out, d_in, B, H);
  };

  //lauch and verify
  launch(); HIP_CHECK(hipDeviceSynchronize());
  HIP_CHECK(hipMemcpy(h_out.data(), d_out, out_e*sizeof(bf16), hipMemcpyDeviceToHost));
  host_ref(h_ref, h_in, B, H);

  double max_abs=0, max_rel=0; max_diff(h_out, h_ref, max_abs, max_rel);
  const double atol=2e-2, rtol=6e-2;  // bf16 合理阈值
  bool ok = (max_abs <= atol) || (max_rel <= rtol);
  printf("Check: max_abs=%.4g  max_rel=%.4g  -> %s\n",
         max_abs, max_rel, ok ? "PASS":"FAIL");

  // get latency and gbs
  float us = time_kernel_ms(launch, 5, 100)*1000.f;
  double bytes = (double)(in_e + out_e) * sizeof(bf16);
  double gbs = (bytes / (us*1e-6)) / 1e9;
  printf("Perf: %.3f us/launch | ~BW: %.1f GB/s\n", us, gbs);

  HIP_CHECK(hipFree(d_in)); HIP_CHECK(hipFree(d_out));
}

