enum class ISA { AMX, VEC, RVV, NEON };

inline ISA get_isa(const std::string& isa) {
  if (isa == "amx") {
    return ISA::AMX;
  } else if (isa == "vec") {
    return ISA::VEC;
  } else if (isa == "rvv") {
    return ISA::RVV;
  } else if (isa == "neon") {
    return ISA::NEON;
  } else {
    TORCH_CHECK(false, "Invalid isa type: " + isa);
  }
}

