  m.impl("cutlass_w4a8_mm", TORCH_BOX(&mm));
  m.impl("cutlass_pack_scale_fp8", TORCH_BOX(&pack_scale_fp8));
  m.impl("cutlass_encode_and_reorder_int4b",
         TORCH_BOX(&encode_and_reorder_int4b));
}

