## Debugging Tools

### 1. rocgdb - ROCm Debugger

rocgdb is GDB with ROCm GPU debugging support.

#### Basic Usage

```bash
# Compile with debug symbols
hipcc -g -O0 program.cpp -o program

# Start debugger
rocgdb ./program

# Common commands:
(gdb) break main
(gdb) run
(gdb) next
(gdb) continue
(gdb) quit
```

#### GPU Debugging

```bash
# Set breakpoint in kernel
(gdb) break vectorAdd

# Run until kernel
(gdb) run

# Show GPU threads (lanes)
(gdb) info threads

# Switch to GPU thread
(gdb) thread 2

# Print GPU variable
(gdb) print blockIdx.x
(gdb) print threadIdx.x

# Print local array
(gdb) print data[0]@10
```

#### Example Session

```bash
$ rocgdb ./vector_add

(gdb) break vectorAdd
Breakpoint 1 at 0x401234: file vector_add.cpp, line 15.

(gdb) run
Thread 1 "vector_add" hit Breakpoint 1, vectorAdd (a=0x7fff...) at vector_add.cpp:15

(gdb) print blockIdx.x
$1 = 0

(gdb) print threadIdx.x  
$2 = 0

(gdb) print a[threadIdx.x]
$3 = 1.0

(gdb) continue
```

### 2. HIP Error Checking

#### Comprehensive Error Handling

```cpp
#include <hip/hip_runtime.h>
#include <iostream>
#include <cstdlib>

// Error checking macro
#define HIP_CHECK(call) \
do { \
    hipError_t err = call; \
    if (err != hipSuccess) { \
        std::cerr << "HIP Error: " << hipGetErrorString(err) \
                  << " (" << hipGetErrorName(err) << ")" \
                  << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
        exit(EXIT_FAILURE); \
    } \
} while(0)

// Kernel launch error checking
#define HIP_CHECK_LAST() \
do { \
    hipError_t err = hipGetLastError(); \
    if (err != hipSuccess) { \
        std::cerr << "HIP Kernel Launch Error: " << hipGetErrorString(err) \
                  << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
        exit(EXIT_FAILURE); \
    } \
} while(0)

// Usage example
int main() {
    float *d_data;

    // Check memory allocation
    HIP_CHECK(hipMalloc(&d_data, 1024 * sizeof(float)));

    // Launch kernel
    myKernel<<<10, 256>>>(d_data);
    HIP_CHECK_LAST();

    // Check synchronization
    HIP_CHECK(hipDeviceSynchronize());

    // Check memory copy
    float h_data[1024];
    HIP_CHECK(hipMemcpy(h_data, d_data, 1024 * sizeof(float), 
                        hipMemcpyDeviceToHost));

    HIP_CHECK(hipFree(d_data));

    return 0;
}
```

