```

### Memory Initialization

```cpp
// Set all bytes to 0
hipMemset(d_data, 0, N * sizeof(float));

// Asynchronous operations
hipStream_t stream;
hipStreamCreate(&stream);
hipMemcpyAsync(d_data, h_data, bytes, hipMemcpyHostToDevice, stream);
hipMemsetAsync(d_data, 0, bytes, stream);
