## PyTorch DDP with RCCL

```python
import torch
import torch.nn as nn
import torch.distributed as dist
from torch.nn.parallel import DistributedDataParallel as DDP

def setup(rank, world_size):
    # Initialize process group (uses RCCL on AMD GPUs)
    dist.init_process_group(
        backend='nccl',  # RCCL on AMD, NCCL on NVIDIA
        init_method='env://',
        world_size=world_size,
        rank=rank
    )
    torch.cuda.set_device(rank)

def cleanup():
    dist.destroy_process_group()

def train_ddp(rank, world_size):
    setup(rank, world_size)

    # Create model and wrap with DDP
    model = nn.Linear(10, 10).to(rank)
    ddp_model = DDP(model, device_ids=[rank])

    # Training loop
    optimizer = torch.optim.SGD(ddp_model.parameters(), lr=0.01)

    for epoch in range(10):
        # Forward pass
        outputs = ddp_model(torch.randn(20, 10).to(rank))
        loss = outputs.sum()

        # Backward (gradients sync via RCCL AllReduce)
        optimizer.zero_grad()
        loss.backward()  # RCCL communication here
        optimizer.step()

        if rank == 0:
            print(f"Epoch {epoch}, Loss: {loss.item()}")

    cleanup()

# Launch with torchrun
# torchrun --nproc_per_node=4 train.py
```

## Multi-Node Training

```python
# Launch on each node:
# Node 0 (master):
# torchrun --nproc_per_node=4 --nnodes=2 --node_rank=0 \
#          --master_addr="192.168.1.1" --master_port=29500 train.py

# Node 1:
# torchrun --nproc_per_node=4 --nnodes=2 --node_rank=1 \
#          --master_addr="192.168.1.1" --master_port=29500 train.py

import os
import torch.distributed as dist

def setup_multinode():
    # Get rank and world_size from environment
    rank = int(os.environ['RANK'])
    local_rank = int(os.environ['LOCAL_RANK'])
    world_size = int(os.environ['WORLD_SIZE'])

    # Initialize
    dist.init_process_group(
        backend='nccl',
        init_method='env://',
        world_size=world_size,
        rank=rank
    )

    torch.cuda.set_device(local_rank)
    return rank, local_rank, world_size
```

