    float elapsed_ms;
    hipEventElapsedTime(&elapsed_ms, start, stop);
    elapsed_ms /= 100.0f;

    size_t bytes = num_elements * sizeof(float) * 2;
    float bandwidth = (bytes / 1e9) / (elapsed_ms / 1000.0f);

    hipEventDestroy(start);
    hipEventDestroy(stop);

