    // Multi-D GEMM epilogue
    template <typename Problem, index_t NumD>
    struct MultiDEpilogue
    {
        CK_TILE_DEVICE void operator()(
            AccType* c_acc,
            const std::array<const DType*, NumD>& d_ptrs,
            OutputType* output,
            index_t m, index_t n)
