    else if constexpr(Phase == 3) {}

    // After optimization: VALU + SALU scheduling
    else if constexpr(Phase == 1)
    {
        __builtin_amdgcn_sched_group_barrier(0x002, 2, 0); // VALU
        __builtin_amdgcn_sched_group_barrier(0x004, 4, 0); // SALU
    }
    else if constexpr(Phase == 3)
    {
        __builtin_amdgcn_sched_group_barrier(0x002, 2, 0); // VALU
        __builtin_amdgcn_sched_group_barrier(0x004, 4, 0); // SALU
    }
    ```

