        // GFX950-specific shuffle
        return __builtin_amdgcn_ds_bpermute(src_lane << 2, val);
    #else
        // Standard shuffle for other architectures
        return __builtin_amdgcn_ds_swizzle(val, src_lane);
    #endif
    }
