        static constexpr fp8_t e2m1_to_fp8_table[16] = {
            fp8_t(static_cast<uint8_t>(0x00)), //  0
            fp8_t(static_cast<uint8_t>(0x30)), //  0.5
            fp8_t(static_cast<uint8_t>(0x38)), //  1
