    __device__ int getPhysicalBlock(
        const int* block_table, int batch_idx, 
        int seq_pos, int block_size, int max_blocks) {
        int block_idx = seq_pos / block_size;
        return block_table[batch_idx * max_blocks + block_idx];
    }
