## Nvidia GPU Architecture

### Hopper Architecture (H100/H200)

```
┌─────────────────────────────────────────────┐
│          H100 GPU (Hopper)                   │
├─────────────────────────────────────────────┤
│  SMs (Streaming Multiprocessors): 132       │
│  └─ Each SM has 4 warp schedulers           │
│     └─ Each schedules 32-thread warps       │
│                                              │
│  Memory Hierarchy:                           │
│  ├─ HBM3: 80 GB @ 3.35 TB/s                │
│  ├─ L2 Cache: 50 MB                         │
│  ├─ L1 Cache/Shared: 256 KB per SM         │
│  └─ Registers: 65,536 per SM               │
│                                              │
│  Peak Performance:                           │
│  ├─ FP32: 67 TFLOPS                         │
│  ├─ FP16 Tensor Core: 1,979 TFLOPS         │
│  └─ FP8 Tensor Core: 3,958 TFLOPS          │
└─────────────────────────────────────────────┘
```

**Key Features:**
- **Warp Size:** 32 threads
- **SMs:** Similar to AMD CUs
- **Shared Memory:** Fast on-chip memory
- **Tensor Cores:** Specialized for matrix operations

## CUDA Programming Model

### Hello World Kernel

```cuda
#include <cuda_runtime.h>
#include <iostream>

__global__ void vectorAdd(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

int main() {
    const int N = 1024;
    size_t bytes = N * sizeof(float);

    // Host memory
    float *h_A = new float[N];
    float *h_B = new float[N];
    float *h_C = new float[N];

    // Initialize
    for (int i = 0; i < N; i++) {
        h_A[i] = i;
        h_B[i] = i * 2.0f;
    }

    // Device memory
    float *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, bytes);
    cudaMalloc(&d_B, bytes);
    cudaMalloc(&d_C, bytes);

    // Copy to device
    cudaMemcpy(d_A, h_A, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, bytes, cudaMemcpyHostToDevice);

    // Launch: 4 blocks × 256 threads
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    vectorAdd<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, N);

    // Copy result back
    cudaMemcpy(h_C, d_C, bytes, cudaMemcpyDeviceToHost);

    // Verify
    bool success = true;
    for (int i = 0; i < N; i++) {
        if (h_C[i] != h_A[i] + h_B[i]) {
            success = false;
            break;
        }
    }

    std::cout << (success ? "PASS" : "FAIL") << std::endl;

    // Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
    delete[] h_A;
    delete[] h_B;
    delete[] h_C;

    return 0;
}
```

