## Unified Memory

```cuda
// Allocate unified memory
float* data;
cudaMallocManaged(&data, N * sizeof(float));

// Access from host
for (int i = 0; i < N; i++) {
    data[i] = i;
}

// Access from device (automatic migration)
myKernel<<<grid, block>>>(data, N);
cudaDeviceSynchronize();

// Access from host again
